  1919	func sourceMaterializationDiffers(root, commit string, entries []ReviewBundleSubjectEntry) string {
  1920		if commit == "" || !hasGitMetadata(root) {
  1921			// No sealed commit, or no repository at all: nothing to compare with (a dispatch has both).
  1922			return ""
  1923		}
  1924		checkedDirs := map[string]bool{}
  1925		for _, entry := range entries {
  1926			if entry.Class == "submodule" {
  1927				continue
  1928			}
  1929			// The absence the bundle sealed is part of what it reviewed: a removed path, and the old
  1930			// side of a rename, must still be absent, whatever Git was told to ignore.
  1931			for _, gone := range removedSides(entry) {
  1932				if _, err := os.Lstat(filepath.Join(root, filepath.FromSlash(gone))); err == nil {
  1933					return gone + " (the bundle sealed it as removed, and it is there)"
  1934				}
  1935			}
  1936			if entry.Action == "removed" {
  1937				continue
  1938			}
  1939			rel := reviewBundleEntryPath(entry)
  1940			if linkAbove(root, rel, checkedDirs) {
  1941				return rel + " (a directory above it is a link, or not a directory)"
  1942			}
  1943			out, err := gitCommand("-C", root, "ls-tree", "-z", commit, "--", rel).Output()
  1944			if err != nil {
  1945				return rel + " (its record in the sealed commit could not be read: " + err.Error() + ")"
  1946			}
  1947			meta, _, ok := strings.Cut(strings.TrimSuffix(string(out), "\x00"), "\t")
  1948			fields := strings.Fields(meta)
  1949			if !ok || len(fields) < 3 {
  1950				continue // not in the sealed commit
  1951			}
  1952			mode, object := fields[0], fields[2]
  1953			info, lerr := os.Lstat(filepath.Join(root, filepath.FromSlash(rel)))
  1954			if lerr != nil {
  1955				return rel + " (it cannot be inspected: " + lerr.Error() + ")"
  1956			}
  1957			switch mode {
  1958			case "120000":
  1959				target, rerr := os.Readlink(filepath.Join(root, filepath.FromSlash(rel)))
  1960				if info.Mode()&os.ModeSymlink == 0 || rerr != nil || gitBlobID("sha1", []byte(target)) != object && gitBlobID("sha256", []byte(target)) != object {
  1961					return rel + " (it is not the link the sealed commit records)"
  1962				}
  1963			default:
  1964				if !info.Mode().IsRegular() {
  1965					return rel + " (it is not a regular file, and the sealed commit records one)"
  1966				}
  1967				if runtime.GOOS != "windows" && (info.Mode().Perm()&0o111 != 0) != (mode == "100755") {
  1968					return rel + " (its executable bit differs)"
  1969				}
  1970			}
  1971		}
  1972		return ""
  1973	}

