   115	// reapShimSubtree ends and reaps every child of the shim, including the
   116	// orphans its subreaper status adopted, until none is left.
   117	func reapShimSubtree() ([]string, error) {
   118		self := os.Getpid()
   119		var ended []string
   120		seen := map[int]bool{}
   121		deadline := time.Now().Add(reviewReapWait)
   122		for {
   123			dirs, err := os.ReadDir("/proc")
   124			if err != nil {
   125				return ended, fmt.Errorf("the run's processes could not be listed: %w", err)
   126			}
   127			children := 0
   128			for _, d := range dirs {
   129				pid, err := strconv.Atoi(d.Name())
   130				if err != nil || pid == self {
   131					continue
   132				}
   133				st, err := readShimProcStat(pid)
   134				if reviewProcessGoneErr(err) {
   135					continue
   136				}
   137				if err != nil {
   138					return ended, fmt.Errorf("process %d could not be inspected: %w", pid, err)
   139				}
   140				if st.ppid != self {
   141					continue
   142				}
   143				children++
   144				if !st.zombie {
   145					if !seen[pid] {
   146						seen[pid] = true
   147						ended = append(ended, strconv.Itoa(pid))
   148					}
   149					if err := killPinnedChild(pid, self); err != nil {
   150						return ended, err
   151					}
   152				}
   153			}
   154			for {
   155				pid, err := unix.Wait4(-1, nil, unix.WNOHANG, nil)
   156				if pid <= 0 || err != nil {
   157					break
   158				}
   159			}
   160			if children == 0 {
   161				return ended, nil
   162			}
   163			if time.Now().After(deadline) {
   164				return ended, fmt.Errorf("%d process(es) of the run could not be ended", children)
   165			}
   166			time.Sleep(20 * time.Millisecond)
   167		}
   168	}
