   175	func readShimProcStat(pid int) (shimProcStat, error) {
   176		raw, err := os.ReadFile("/proc/" + strconv.Itoa(pid) + "/stat")
   177		if err != nil {
   178			return shimProcStat{}, err
   179		}
   180		text := string(raw)
   181		end := strings.LastIndexByte(text, ')')
   182		if end < 0 {
   183			return shimProcStat{}, fmt.Errorf("process %d stat is unreadable", pid)
   184		}
   185		f := strings.Fields(text[end+1:])
   186		if len(f) < 2 {
   187			return shimProcStat{}, fmt.Errorf("process %d stat is unreadable", pid)
   188		}
   189		ppid, err := strconv.Atoi(f[1])
   190		if err != nil {
   191			return shimProcStat{}, fmt.Errorf("process %d stat is unreadable", pid)
   192		}
   193		return shimProcStat{ppid: ppid, zombie: f[0] == "Z"}, nil
   194	}
