   197	// parent: a pid reused by an unrelated process is never signalled.
   198	func killPinnedChild(pid, parent int) error {
   199		fd, err := unix.PidfdOpen(pid, 0)
   200		if errors.Is(err, unix.ESRCH) {
   201			return nil
   202		}
   203		if err != nil {
   204			return fmt.Errorf("process %d could not be pinned: %w", pid, err)
